INSERT INTO skills (code, subject_code, name) VALUES
    ('PLACE_VALUE_G4', 'MATH', 'Large Numbers and Place Value'),
    ('PRONOUNS_G4', 'ENGLISH', 'Pronouns');
INSERT INTO lessons (id, code, subject_code, grade_level, display_order, title, description) VALUES
    ('15000000-0000-0000-0000-000000000018', 'G4-PLACE-01', 'MATH', 'GRADE_4', 10, 'Large Numbers and Place Value', 'Read, compare, and round numbers into the thousands.'),
    ('15000000-0000-0000-0000-000000000019', 'G4-ENG-PRONOUN-01', 'ENGLISH', 'GRADE_4', 9, 'Pronouns', 'Use words like he, she, they, and it in place of nouns.');
INSERT INTO exercises (id, lesson_code, skill_code, display_order, prompt, answer_index, explanation, hint) VALUES
    ('35000000-0000-0000-0000-000000000001', 'G4-MULT-01', 'MULT_MULTIDIGIT', 4, 'What is 42 x 5?', 1, '40 x 5 = 200 and 2 x 5 = 10, so 210.', 'Split 42 into 40 + 2.'),
    ('35000000-0000-0000-0000-000000000002', 'G4-MULT-01', 'MULT_MULTIDIGIT', 5, 'What is 12 x 12?', 2, '12 x 12 = 144.', '10 x 12 = 120, plus 2 x 12 = 24.'),
    ('35000000-0000-0000-0000-000000000003', 'G4-MULT-01', 'MULT_MULTIDIGIT', 6, 'What is 25 x 8?', 2, '25 x 8 = 200. Four 25s make 100, so eight make 200.', 'Think about quarters.'),
    ('35000000-0000-0000-0000-000000000004', 'G4-DIV-01', 'LONG_DIV', 4, 'What is 65 / 5?', 2, '65 / 5 = 13, because 5 x 13 = 65.', '50 / 5 = 10, and 15 / 5 = 3.'),
    ('35000000-0000-0000-0000-000000000005', 'G4-DIV-01', 'LONG_DIV', 5, 'What is 120 / 10?', 1, '120 / 10 = 12.', 'Dividing by 10 removes a zero.'),
    ('35000000-0000-0000-0000-000000000006', 'G4-DIV-01', 'LONG_DIV', 6, 'What is 23 / 4? (quotient and remainder)', 2, '4 x 5 = 20, and 23 - 20 = 3 left over.', 'Find the biggest multiple of 4 under 23.'),
    ('35000000-0000-0000-0000-000000000007', 'G4-FRACEQ-01', 'FRAC_EQUIV', 4, 'Which fraction equals 3/4?', 0, 'Multiply top and bottom by 2: 3/4 = 6/8.', 'Multiply both numbers by the same thing.'),
    ('35000000-0000-0000-0000-000000000008', 'G4-FRACEQ-01', 'FRAC_EQUIV', 5, 'Which fraction equals 1/3?', 2, '1/3 = 2/6 (times 2 on top and bottom).', 'Double both numbers.'),
    ('35000000-0000-0000-0000-000000000009', 'G4-FRACEQ-01', 'FRAC_EQUIV', 6, 'Simplify 5/10.', 1, 'Divide both by 5: 5/10 = 1/2.', 'What divides both 5 and 10?'),
    ('35000000-0000-0000-0000-000000000010', 'G4-FRACCOMP-01', 'FRAC_COMPARE', 4, 'Which fraction is bigger: 3/8 or 5/8?', 2, 'Same bottom number, so the bigger top wins: 5/8.', 'Same-size pieces: more pieces is bigger.'),
    ('35000000-0000-0000-0000-000000000011', 'G4-FRACCOMP-01', 'FRAC_COMPARE', 5, 'Which fraction is bigger: 1/3 or 1/5?', 1, 'Thirds are bigger pieces than fifths.', 'Fewer pieces means each piece is bigger.'),
    ('35000000-0000-0000-0000-000000000012', 'G4-FRACCOMP-01', 'FRAC_COMPARE', 6, 'Which is true?', 2, '2/4 simplifies to 1/2, so they are equal.', 'Simplify 2/4.'),
    ('35000000-0000-0000-0000-000000000013', 'G4-DECIMAL-01', 'DECIMALS_INTRO', 4, 'What is 0.25 as a fraction?', 2, '0.25 = 25/100 = 1/4.', 'Think of a quarter of a dollar.'),
    ('35000000-0000-0000-0000-000000000014', 'G4-DECIMAL-01', 'DECIMALS_INTRO', 5, 'Which is bigger: 0.6 or 0.45?', 2, '0.6 = 0.60, which is more than 0.45.', 'Add a zero: 0.60 vs 0.45.'),
    ('35000000-0000-0000-0000-000000000015', 'G4-DECIMAL-01', 'DECIMALS_INTRO', 6, 'What is 3.2 - 1.1?', 0, '3.2 - 1.1 = 2.1.', 'Subtract each place.'),
    ('35000000-0000-0000-0000-000000000016', 'G4-FACTOR-01', 'FACTORS_MULTIPLES', 4, 'Which list shows all the factors of 6?', 2, '1 x 6 and 2 x 3 make 6.', 'Find every pair that multiplies to 6.'),
    ('35000000-0000-0000-0000-000000000017', 'G4-FACTOR-01', 'FACTORS_MULTIPLES', 5, 'Which number is a multiple of 3?', 0, '3 x 7 = 21.', 'Count by 3s.'),
    ('35000000-0000-0000-0000-000000000018', 'G4-FACTOR-01', 'FACTORS_MULTIPLES', 6, 'Which number is a factor of both 8 and 12?', 0, '4 divides 8 and 12 evenly.', 'Try dividing both numbers.'),
    ('35000000-0000-0000-0000-000000000019', 'G4-ANGLE-01', 'ANGLES_G4', 4, 'How many degrees are in a right angle?', 0, 'A right angle is 90 degrees.', 'Like the corner of a book.'),
    ('35000000-0000-0000-0000-000000000020', 'G4-ANGLE-01', 'ANGLES_G4', 5, 'What do we call an angle that is exactly 180 degrees?', 1, '180 degrees makes a straight line.', 'It looks like a line.'),
    ('35000000-0000-0000-0000-000000000021', 'G4-ANGLE-01', 'ANGLES_G4', 6, 'How many right angles does a rectangle have?', 1, 'Every corner of a rectangle is a right angle.', 'Count the corners.'),
    ('35000000-0000-0000-0000-000000000022', 'G4-WORD-01', 'WORD_PROB_G4', 4, 'A school buys 4 boxes of 25 markers and uses 30. How many are left?', 0, '4 x 25 = 100, then 100 - 30 = 70.', 'First find the total.'),
    ('35000000-0000-0000-0000-000000000023', 'G4-WORD-01', 'WORD_PROB_G4', 5, 'Mia reads 15 pages a day for 6 days. Her book has 120 pages. How many pages are left?', 1, '15 x 6 = 90, then 120 - 90 = 30.', 'Find how many she has read.'),
    ('35000000-0000-0000-0000-000000000024', 'G4-WORD-01', 'WORD_PROB_G4', 6, 'Tickets cost $7 each. A family buys 5 tickets and pays with $50. How much change do they get?', 2, '5 x 7 = 35, then 50 - 35 = 15.', 'Find the cost first.'),
    ('35000000-0000-0000-0000-000000000025', 'G4-AREA-01', 'AREA_PERIMETER_G4', 4, 'A square garden has sides of 9 feet. What is its area?', 1, 'Area = 9 x 9 = 81 square feet.', 'Side times side.'),
    ('35000000-0000-0000-0000-000000000026', 'G4-AREA-01', 'AREA_PERIMETER_G4', 5, 'A rectangle has an area of 24 and a length of 6. What is its width?', 1, '24 / 6 = 4.', 'Area = length x width.'),
    ('35000000-0000-0000-0000-000000000027', 'G4-AREA-01', 'AREA_PERIMETER_G4', 6, 'A rectangle is 12 cm long and 3 cm wide. What is its perimeter?', 1, '12 + 3 + 12 + 3 = 30 cm.', 'Add all four sides.'),
    ('35000000-0000-0000-0000-000000000028', 'G4-ENG-COMP-01', 'COMPREHENSION_G4', 4, 'Read: "Jada checked the map twice and packed extra water before the hike." What does this show about Jada?', 1, 'Checking twice and packing extra shows careful planning.', 'What do her actions suggest?'),
    ('35000000-0000-0000-0000-000000000029', 'G4-ENG-COMP-01', 'COMPREHENSION_G4', 5, 'Read: "The crowd fell silent as the last runner limped across the finish line, then burst into cheers." Why did the crowd cheer?', 1, 'The runner was limping but still finished.', 'What does "limped" tell you?'),
    ('35000000-0000-0000-0000-000000000030', 'G4-ENG-COMP-01', 'COMPREHENSION_G4', 6, 'Read: "Water dripped from Marco''s coat, and he shook out his umbrella." What was the weather?', 1, 'Dripping water and an umbrella suggest rain.', 'Why would you need an umbrella?'),
    ('35000000-0000-0000-0000-000000000031', 'G4-ENG-FIGLANG-01', 'FIGURATIVE_LANG', 4, '"The classroom was a zoo" is an example of what?', 0, 'It says the classroom IS a zoo, without like or as.', 'Does it use "like" or "as"?'),
    ('35000000-0000-0000-0000-000000000032', 'G4-ENG-FIGLANG-01', 'FIGURATIVE_LANG', 5, '"She is as busy as a bee" is an example of what?', 2, 'It compares using "as".', 'Look for like or as.'),
    ('35000000-0000-0000-0000-000000000033', 'G4-ENG-FIGLANG-01', 'FIGURATIVE_LANG', 6, 'What does the idiom "it''s raining cats and dogs" mean?', 0, 'It''s an idiom meaning heavy rain.', 'Idioms don''t mean exactly what they say.'),
    ('35000000-0000-0000-0000-000000000034', 'G4-ENG-MAINIDEA-01', 'MAIN_IDEA_DETAILS', 4, 'Read: "Sharks have rows of sharp teeth, a keen sense of smell, and speed." What is the main idea?', 1, 'All the details explain how sharks hunt well.', 'What do the details add up to?'),
    ('35000000-0000-0000-0000-000000000035', 'G4-ENG-MAINIDEA-01', 'MAIN_IDEA_DETAILS', 5, 'Where is the main idea often found in a paragraph?', 1, 'The topic sentence is often first.', 'Look at how paragraphs begin.'),
    ('35000000-0000-0000-0000-000000000036', 'G4-ENG-MAINIDEA-01', 'MAIN_IDEA_DETAILS', 6, 'Read: "Recycling saves trees, reduces trash, and saves energy." Which is a detail?', 1, 'Reducing trash is one specific supporting fact.', 'A detail is one specific fact.'),
    ('35000000-0000-0000-0000-000000000037', 'G4-ENG-SUMMARY-01', 'SUMMARIZING', 4, 'A summary should NOT include:', 2, 'A summary retells the main points, not your feelings.', 'Summaries stay objective.'),
    ('35000000-0000-0000-0000-000000000038', 'G4-ENG-SUMMARY-01', 'SUMMARIZING', 5, 'Which is the best summary of "Goldilocks tries the bears'' food, chairs, and beds, then runs away when they find her"?', 1, 'It covers the whole story in one short line.', 'Cover the beginning, middle, and end briefly.'),
    ('35000000-0000-0000-0000-000000000039', 'G4-ENG-SUMMARY-01', 'SUMMARIZING', 6, 'About how long should a summary be compared to the original?', 0, 'Summaries are short.', 'Summaries only keep the key points.'),
    ('35000000-0000-0000-0000-000000000040', 'G4-ENG-TENSE-01', 'VERB_TENSES', 4, 'What is the past tense of "run"?', 1, 'Run is irregular: run becomes ran.', 'This verb doesn''t use -ed.'),
    ('35000000-0000-0000-0000-000000000041', 'G4-ENG-TENSE-01', 'VERB_TENSES', 5, 'Which sentence tells about something that has not happened yet?', 1, '"Will" shows the future.', 'Look for "will".'),
    ('35000000-0000-0000-0000-000000000042', 'G4-ENG-TENSE-01', 'VERB_TENSES', 6, 'What is the past tense of "bring"?', 0, 'Bring is irregular: brought.', 'Think: "I ___ my lunch."'),
    ('35000000-0000-0000-0000-000000000043', 'G4-ENG-VOCAB-01', 'VOCAB_G4', 4, 'What does "fragile" mean?', 0, 'Fragile things break easily, like glass.', 'Boxes with glass say this.'),
    ('35000000-0000-0000-0000-000000000044', 'G4-ENG-VOCAB-01', 'VOCAB_G4', 5, 'What does "generous" mean?', 0, 'A generous person gives and shares.', 'The opposite of selfish.'),
    ('35000000-0000-0000-0000-000000000045', 'G4-ENG-VOCAB-01', 'VOCAB_G4', 6, 'What does "ancient" mean?', 2, 'Ancient means from long ago.', 'Think of dinosaurs or pyramids.'),
    ('35000000-0000-0000-0000-000000000046', 'G4-ENG-STRUCT-01', 'TEXT_STRUCTURE', 4, 'A passage that describes a problem and how it was fixed uses what structure?', 2, 'It names a problem and gives a solution.', 'Look for a problem and a fix.'),
    ('35000000-0000-0000-0000-000000000047', 'G4-ENG-STRUCT-01', 'TEXT_STRUCTURE', 5, 'Which signal words show sequence?', 2, 'Sequence words show order.', 'Which words show order?'),
    ('35000000-0000-0000-0000-000000000048', 'G4-ENG-STRUCT-01', 'TEXT_STRUCTURE', 6, 'A recipe is usually written in what structure?', 0, 'Recipes list steps in order.', 'Recipes go step by step.'),
    ('35000000-0000-0000-0000-000000000049', 'G4-ENG-PURPOSE-01', 'AUTHORS_PURPOSE', 4, 'A poster that says "Vote for Kim — she''ll make recess longer!" has what purpose?', 2, 'It tries to get you to vote.', 'Is it trying to change your mind?'),
    ('35000000-0000-0000-0000-000000000050', 'G4-ENG-PURPOSE-01', 'AUTHORS_PURPOSE', 5, 'A funny comic strip has what purpose?', 1, 'Comics are meant to amuse.', 'Why do you read comics?'),
    ('35000000-0000-0000-0000-000000000051', 'G4-ENG-PURPOSE-01', 'AUTHORS_PURPOSE', 6, 'An encyclopedia entry about sharks has what purpose?', 1, 'It gives facts.', 'Does it teach facts?'),
    ('35000000-0000-0000-0000-000000000052', 'G4-PLACE-01', 'PLACE_VALUE_G4', 1, 'What is the value of the 7 in 7,425?', 2, 'The 7 is in the thousands place: 7,000.', 'Count the places from the right.'),
    ('35000000-0000-0000-0000-000000000053', 'G4-PLACE-01', 'PLACE_VALUE_G4', 2, 'How do you write "three thousand, two hundred six"?', 0, '3 thousands, 2 hundreds, 0 tens, 6 ones: 3,206.', 'Don''t forget the zero tens.'),
    ('35000000-0000-0000-0000-000000000054', 'G4-PLACE-01', 'PLACE_VALUE_G4', 3, 'Which number is greatest?', 2, 'All have 5 thousands; 5,301 has the most hundreds.', 'Compare place by place.'),
    ('35000000-0000-0000-0000-000000000055', 'G4-PLACE-01', 'PLACE_VALUE_G4', 4, 'Round 4,682 to the nearest thousand.', 1, 'The hundreds digit is 6, so round up to 5,000.', 'Look at the hundreds digit.'),
    ('35000000-0000-0000-0000-000000000056', 'G4-PLACE-01', 'PLACE_VALUE_G4', 5, 'What is 1,000 more than 2,450?', 0, 'Add 1 to the thousands: 3,450.', 'Only the thousands digit changes.'),
    ('35000000-0000-0000-0000-000000000057', 'G4-PLACE-01', 'PLACE_VALUE_G4', 6, 'How many hundreds are in 1,000?', 1, '10 hundreds make 1,000.', 'Count by hundreds to 1,000.'),
    ('35000000-0000-0000-0000-000000000058', 'G4-ENG-PRONOUN-01', 'PRONOUNS_G4', 1, 'Which pronoun can replace "Maria" in "Maria likes art"?', 1, 'Maria is one girl: she.', 'Use a word for one girl.'),
    ('35000000-0000-0000-0000-000000000059', 'G4-ENG-PRONOUN-01', 'PRONOUNS_G4', 2, 'Which pronoun can replace "the dogs" in "The dogs barked"?', 1, 'More than one dog: they.', 'More than one thing.'),
    ('35000000-0000-0000-0000-000000000060', 'G4-ENG-PRONOUN-01', 'PRONOUNS_G4', 3, 'Which word is a pronoun?', 2, '"it" stands in for a noun.', 'Which word replaces a noun?'),
    ('35000000-0000-0000-0000-000000000061', 'G4-ENG-PRONOUN-01', 'PRONOUNS_G4', 4, 'Which sentence uses a pronoun correctly?', 0, 'Use "I" when you are doing the action.', 'Take Ben out: "I went home."'),
    ('35000000-0000-0000-0000-000000000062', 'G4-ENG-PRONOUN-01', 'PRONOUNS_G4', 5, 'Which pronoun fits: "The book is ___."', 2, '"Mine" shows it belongs to you.', 'Who does it belong to?'),
    ('35000000-0000-0000-0000-000000000063', 'G4-ENG-PRONOUN-01', 'PRONOUNS_G4', 6, 'In "Leo lost his hat," which word is a pronoun?', 0, '"his" stands in for Leo''s.', 'Which word replaces Leo''s?');
